/**
 * @method
 * @name img_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_Excel_onclick = async function() {
    try {
        $c.stf.doLogSave("ULDSTF05916.xml", SCREN_PROCS_TP_CD_07);
        if (dts.getRowCount() > 0) {
            $c.data.downloadGridViewExcel(grd, {fileName: $c.lc.fn_getSecuGrpNm(scwin.fr_SecuGrpId) + "상장폐지내역", type: "8"});
        } else {
            await $c.win.alert(NO_EXCEL_DATA);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05916.img_Excel_onclick" });
    }
};

