        //                      "&DIV_IDX="+DIV_IDX_DELLIST_LIST_KO + "&TRS_IDX="+TRS_IDX_SELECT + "&ISUR_CD=99999"  ;
        "&DIV_IDX=" + DIV_IDX_DELLIST_LIST_KO + "&TRS_IDX=" + TRS_IDX_SELECT + "&ISUR_CD=99999" + "&GUBUN_CD=" + "690019";
    url += "&SCREN_ID=" + "ULDSTF05916.xml";
