/**
 * @method
 * @name newpreCreateFrame
 * @description newpre Create Frame 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.newpreCreateFrame = async function() {
    const options = {
        id: "ULDSTF05917",
        title: $c.lc.fn_getSecuGrpNm(scwin.fr_SecuGrpId) + " 상장폐지",
        type: "browserPopup",
        width: "720px",
        height: "530px",
        callbackFn: "scwin.popupCallback"
    };

    $c.win.openPopup("../lstproc/ULDSTF05917.gfm", options);
    await scwin.search(); // 다이얼로그 창이 닫히면 조회를 보낸다.

};

